/** Same limit as the API's default (`DEFAULT_MAX_IMAGE_BYTES`). */
export const MAX_UPLOAD_BYTES = 10 * 1024 * 1024;
export const UPLOAD_TYPES = ["image/png", "image/jpeg"] as const;
